      "asserted_values": ["0xEDB88320"],
      "confidence": 1.0
    },
    {
      "id": "2",
      "type": "IO",
      "text": "Returns 0xFFFFFFFF when the input length is 0.",
      "asserted_values": ["0xFFFFFFFF"],
      "confidence": 1.0,
      "io": {
        "when": "param_2 == 0",
        "returns": "0xFFFFFFFF"
      }
    },
    {
      "id": "3",
      "type": "SIDE",
      "text": "Writes the 4-byte CRC-32 checksum to the output buffer.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "4",
      "type": "CF",
      "text": "The function uses a nested loop to compute the CRC-32 checksum.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_01(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len != 0) {\n    uint32_t crc = 0xFFFFFFFF;\n    for (size_t i = 0; i < len; i++) {\n      crc ^= in[i];\n      for (int j = 0; j < 8; j++) {\n        crc = -(crc & 1) & 0xEDB88320 ^ crc >> 1;\n      }\n    }\n    *out = crc & 0xFF;\n    *(out + 1) = (crc >> 8) & 0xFF;\n    *(out + 2) = (crc >> 16) & 0xFF;\n    *(out + 3) = (crc >> 24) & 0xFF;\n    return crc;\n  }\n  return VERA_ERR;\n}"
}
